    {
      "text": "The source campaign promoted corporate events at a venue. Do not describe it as a wedding campaign or its visitors as couples.",
      "kind": "do_not_claim",
      "required": true,
      "answer": null
    },
    {
      "text": "Do not imply Jacqueline reviewed the page, changes were implemented, a cause was established or results improved.",
